const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog'),engine=new AudioEngine();
let project=null,history=new History(),selection={},view='piano',zoom=36,grid=.25,octave=4,noteLength=1,assistantOpen=false,messages=[],pending=null,saveTimer,saveQueue=Promise.resolve(),dirty=false,revision=0,record=null,clipboard=null,search='',beginner=localStorage.getItem('lyes-niveau')!=='expert';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=`<div class="brand"><b>L</b>LYES</div>`;
const track=()=>project?.tracks.find(t=>t.id===selection.trackId);
